// Plan task M11.3: the Query page is kept alive while another page is shown.
test('Back to the Query page shows the results where they were left, without running the query again', async ({ page }) => {
	await page.setViewportSize({ width: 1440, height: 900 });
	// The result card's reveal is otherwise a smooth scroll that WebKit keeps animating over the scroll below.
	await page.emulateMedia({ reducedMotion: 'reduce' });
	await openRoute(page, 'query');
	const values = Array.from({ length: 400 }, (_, index) => String(index)).join(' ');
	const text = `SELECT ?item WHERE { VALUES ?item { ${values} } }`;
	await page.locator('.CodeMirror').first().evaluate((element, query) => element.CodeMirror.setValue(query), text);
	await page.locator('#exec').click();
	await expect(page.locator('#query-results .query-result-status')).toContainText('400 rows');
	// The table renders a window of rows that it reuses, so compare the first row fully in view instead.
	const visibleRow = () => page.evaluate(() => {
		const rows = Array.from(document.querySelectorAll('#query-results tbody tr[data-query-row-index]'));
		const shown = rows.find((element) => {
			const box = element.getBoundingClientRect();
			return box.top >= 80 && box.bottom <= window.innerHeight;
		});
		return shown ? Number(shown.getAttribute('data-query-row-index')) : null;
	});
	await page.evaluate(() => window.scrollTo(0, document.documentElement.scrollHeight / 2));
	await expect.poll(visibleRow).toBeGreaterThan(100);
	const left = await visibleRow();
	const executions = [];
	page.on('request', (request) => {
		if (request.method() === 'POST' && (request.postData() || '').includes('action=exec')) {
			executions.push(request.url());
		}
	});

	await menuLink(page, 'Summary').click();
	await expectRoute(page, 'summary');
	await page.goBack();
	await expectRoute(page, 'query');

	await expect.poll(visibleRow).toBe(left);
	expect(await page.locator('.CodeMirror').first().evaluate((element) => element.CodeMirror.getValue())).toBe(text);
	expect(executions).toEqual([]);
	for (let round = 0; round < 10; round++) {
		await menuLink(page, 'Summary').click();
		await expectRoute(page, 'summary');
		expect(await page.locator('#workbench-kept-alive > *').count()).toBeLessThanOrEqual(1);
		await page.goBack();
		await expectRoute(page, 'query');
	}
	expect(await page.locator('#workbench-kept-alive > *').count()).toBe(0);
	expect(await page.locator('.CodeMirror').count()).toBe(1);
	expect(executions).toEqual([]);
});

test('Explore links and the Explore form change the page without loading a document', async ({ page }) => {
	await page.setViewportSize({ width: 1440, height: 900 });
	const pageErrors = [];
	page.on('pageerror', (error) => pageErrors.push(error.message));
	const type = '<http://www.w3.org/1999/02/22-rdf-syntax-ns#type>';
	await page.goto(`${repositoryPageUrl(REPOSITORY_ID, 'explore')}?resource=${encodeURIComponent(type)}`);
	await waitForRoute(page, 'explore');
	await expect(page.locator('#explore-result-count')).toHaveText(/^Rows 1–/);
	const documents = recordDocumentRequests(page);

	// Another resource from the results (each page shows the explored resource's statements).
	const link = page.locator('#explore-results a[href*="explore?resource="]')
		.filter({ hasNotText: 'rdf:type' }).first();
	const target = new URL(await link.getAttribute('href'), page.url()).searchParams.get('resource');
	await link.click();
	await waitForRoute(page, 'explore', { url: (url) => url.searchParams.get('resource') === target });
	await expect(page.locator('#resource')).toHaveValue(target);
	await expect(page.locator('#explore-result-count')).toHaveText(/^Rows 1–/);

	// The form, with another result limit.
	await page.locator('#explore-result-options-toggle').click();
	await page.locator('#limit_explore').selectOption('10');
	await page.locator('#resource').fill(type);
	await page.locator('#resource').press('Enter');
	await waitForRoute(page, 'explore', { url: (url) => url.searchParams.get('limit_explore') === '10' });
	await expect(page.locator('#explore-result-count')).toHaveText(/^Rows 1–10\b/);

	expect(documents).toEqual([]);
	expect(pageErrors).toEqual([]);
});

test('deleting a saved query shows the remaining ones without loading a document', async ({ page }) => {
	await page.setViewportSize({ width: 1440, height: 900 });
	const pageErrors = [];
	page.on('pageerror', (error) => pageErrors.push(error.message));
	const names = [`router-delete-a-${Date.now()}`, `router-delete-b-${Date.now()}`];
	await openRoute(page, 'query');
	for (const name of names) {
		await page.locator('.CodeMirror').first().evaluate((element, value) => element.CodeMirror.setValue(value),
			`SELECT ?s WHERE { ?s ?p "${name}" }`);
		if (!(await page.locator('#query-name').isVisible())) {
			await page.locator('#save-query-toggle').press('Enter');
		}
		await page.locator('#query-name').fill(name);
		await page.evaluate(() => window.workbench.query.handleNameChange());
		await page.locator('#save').click();
		await expect(page.locator('#save-feedback')).toContainText('Query saved.');
	}
	await openRoute(page, 'saved-queries');
	const documents = recordDocumentRequests(page);
	const row = (name) => page.locator('.saved-query-row').filter({ has: page.locator('h2', { hasText: name }) });

	await row(names[0]).locator('.saved-query-delete').click();
	await page.getByRole('dialog', { name: 'Delete saved query?' }).getByRole('button', { name: 'Delete' }).click();

	await waitForRoute(page, 'saved-queries', { url: /\/saved-queries\?delete=/ });
	await expect(row(names[0])).toHaveCount(0);
	await expect(row(names[1])).toHaveCount(1);
	await expect(row(names[1])).toBeVisible();
	expect(documents).toEqual([]);
	expect(pageErrors).toEqual([]);
});

// Plan task M13.4 (user request): each repository keeps its Query results in the browser tab.
test('each repository keeps its Query results in the tab, and a new tab starts without them', async ({ page, context, request }) => {
	const other = uniqueRepositoryId('workbench-router-other');
	await createSeededRepository(request, serverBaseUrl(), other, { graphs: [] });
	try {
		await page.setViewportSize({ width: 1440, height: 900 });
		const executions = [];
		page.on('request', (request) => {
			if (request.method() === 'POST' && (request.postData() || '').includes('action=exec')) {
				executions.push(request.url());
			}
		});
		const editor = page.locator('.CodeMirror').first();
		const status = page.locator('#query-results .query-result-status');
		const run = async (items) => {
			const text = `SELECT ?item WHERE { VALUES ?item { ${items.map((item) => `"${item}"`).join(' ')} } }`;
			await editor.evaluate((element, value) => element.CodeMirror.setValue(value), text);
			await page.locator('#exec').click();
			await expect(status).toContainText(`${items.length} rows`);
			return text;
		};
		const switchTo = async (repositoryId) => {
			await page.locator('#workbench-repository-switcher').click();
			await page.locator(`#workbench-repository-options a[data-repository-id="${repositoryId}"]`).click();
			await waitForRoute(page, 'query', { url: new RegExp(`/repositories/${repositoryId}/query$`) });
		};

		await openRoute(page, 'query');
		const first = await run(['a1', 'a2', 'a3']);
		await menuLink(page, 'Summary').click();
		await expectRoute(page, 'summary');
		await menuLink(page, 'Query').click();
		await expectRoute(page, 'query');
		await expect(status).toContainText('3 rows');
		expect(executions).toHaveLength(1);

		await switchTo(other);
		await expect(page.locator('#query-results [data-query-stream-root]')).toHaveCount(0);
		await run(['b1', 'b2']);
		await switchTo(REPOSITORY_ID);
		await expect(status).toContainText('3 rows');
		expect(await editor.evaluate((element) => element.CodeMirror.getValue())).toBe(first);
		await switchTo(other);
		await expect(status).toContainText('2 rows');
		expect(executions, 'no query ran again').toHaveLength(2);

		const second = await context.newPage();
		await second.goto(repositoryPageUrl(REPOSITORY_ID, 'query'));
		await waitForRoute(second, 'query');
		await expect(second.locator('#query-results [data-query-stream-root]')).toHaveCount(0);
		await second.close();
	} finally {
		await deleteRepository(request, serverBaseUrl(), other);
	}
});
